CREATE TABLE IF NOT EXISTS admin_user (
 id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(64) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, enabled TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS category (
 id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(64) NOT NULL, slug VARCHAR(64) NOT NULL UNIQUE, icon VARCHAR(64), description VARCHAR(255), sort_order INT NOT NULL DEFAULT 0, enabled TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tag (
 id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(64) NOT NULL, slug VARCHAR(64) NOT NULL UNIQUE, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, KEY idx_tag_name(name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS game (
 id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(128) NOT NULL, english_name VARCHAR(128), slug VARCHAR(160) NOT NULL UNIQUE, aliases VARCHAR(500), summary VARCHAR(500) NOT NULL, description TEXT, developer VARCHAR(128), publisher VARCHAR(128), release_date DATE, category_id BIGINT NOT NULL, cover_url VARCHAR(500), banner_url VARCHAR(500), cover_hue DOUBLE, cover_chroma DOUBLE, cover_lightness DOUBLE, cover_accent CHAR(7), cover_color_confidence DOUBLE, cover_hue_override DOUBLE, wall_enabled TINYINT(1) NOT NULL DEFAULT 1, current_version VARCHAR(64), file_size VARCHAR(64), status VARCHAR(24) NOT NULL, view_count BIGINT NOT NULL DEFAULT 0, resource_click_count BIGINT NOT NULL DEFAULT 0, published_at DATETIME, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, deleted_at DATETIME NULL,
 KEY idx_game_status(status), KEY idx_game_category(category_id), KEY idx_game_updated(updated_at), KEY idx_game_public_updated(status,deleted_at,updated_at,id), KEY idx_game_category_public(category_id,status,deleted_at,updated_at,id), KEY idx_game_wall(status,deleted_at,wall_enabled,updated_at,id), CONSTRAINT fk_game_category FOREIGN KEY(category_id) REFERENCES category(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS game_tag (game_id BIGINT NOT NULL, tag_id BIGINT NOT NULL, UNIQUE KEY uk_game_tag(game_id,tag_id), KEY idx_gt_tag(tag_id), CONSTRAINT fk_gt_game FOREIGN KEY(game_id) REFERENCES game(id), CONSTRAINT fk_gt_tag FOREIGN KEY(tag_id) REFERENCES tag(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS game_platform (id BIGINT PRIMARY KEY AUTO_INCREMENT, game_id BIGINT NOT NULL, platform VARCHAR(32) NOT NULL, UNIQUE KEY uk_game_platform(game_id,platform), KEY idx_gp_game(game_id), KEY idx_gp_filter(platform,game_id), CONSTRAINT fk_gp_game FOREIGN KEY(game_id) REFERENCES game(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS game_language (id BIGINT PRIMARY KEY AUTO_INCREMENT, game_id BIGINT NOT NULL, language VARCHAR(32) NOT NULL, UNIQUE KEY uk_game_language(game_id,language), KEY idx_gl_game(game_id), KEY idx_gl_filter(language,game_id), CONSTRAINT fk_gl_game FOREIGN KEY(game_id) REFERENCES game(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS game_media (id BIGINT PRIMARY KEY AUTO_INCREMENT, game_id BIGINT NOT NULL, type VARCHAR(24) NOT NULL, url VARCHAR(500) NOT NULL, sort_order INT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, KEY idx_media_game_type(game_id,type), CONSTRAINT fk_media_game FOREIGN KEY(game_id) REFERENCES game(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS game_requirement (id BIGINT PRIMARY KEY AUTO_INCREMENT, game_id BIGINT NOT NULL, type VARCHAR(24) NOT NULL, os VARCHAR(128), cpu VARCHAR(255), gpu VARCHAR(255), memory VARCHAR(64), storage VARCHAR(64), UNIQUE KEY uk_req_game_type(game_id,type), KEY idx_req_game(game_id), CONSTRAINT fk_req_game FOREIGN KEY(game_id) REFERENCES game(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS game_version (id BIGINT PRIMARY KEY AUTO_INCREMENT, game_id BIGINT NOT NULL, version VARCHAR(64) NOT NULL, release_notes TEXT, file_size VARCHAR(64), release_date DATE, is_current TINYINT(1) NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY uk_version_game_version(game_id,version), KEY idx_version_game(game_id), CONSTRAINT fk_version_game FOREIGN KEY(game_id) REFERENCES game(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS resource_link (id BIGINT PRIMARY KEY AUTO_INCREMENT, game_id BIGINT NOT NULL, game_version_id BIGINT NULL, provider VARCHAR(64) NOT NULL, url VARCHAR(1000) NOT NULL, password VARCHAR(64), version VARCHAR(64), status VARCHAR(24) NOT NULL, sort_order INT NOT NULL DEFAULT 0, last_checked_at DATETIME NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, deleted_at DATETIME NULL, KEY idx_link_game(game_id), KEY idx_link_status(status), CONSTRAINT fk_link_game FOREIGN KEY(game_id) REFERENCES game(id), CONSTRAINT fk_link_version FOREIGN KEY(game_version_id) REFERENCES game_version(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS link_report (id BIGINT PRIMARY KEY AUTO_INCREMENT, resource_link_id BIGINT NOT NULL, reason VARCHAR(32) NOT NULL, ip_hash CHAR(64) NOT NULL, user_agent VARCHAR(255), status VARCHAR(24) NOT NULL, created_at DATETIME NOT NULL, processed_at DATETIME NULL, KEY idx_report_link(resource_link_id), KEY idx_report_status(status), CONSTRAINT fk_report_link FOREIGN KEY(resource_link_id) REFERENCES resource_link(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS search_log (id BIGINT PRIMARY KEY AUTO_INCREMENT, keyword VARCHAR(255) NOT NULL, result_count INT NOT NULL, created_at DATETIME NOT NULL, KEY idx_search_created(created_at), KEY idx_search_keyword(keyword)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS operation_log (id BIGINT PRIMARY KEY AUTO_INCREMENT, admin_id BIGINT, operation VARCHAR(128) NOT NULL, target_type VARCHAR(64), target_id BIGINT, ip VARCHAR(64), created_at DATETIME NOT NULL, KEY idx_op_admin(admin_id), KEY idx_op_created(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;



